}

function tokensOf(text) {
  const out = [];
  let current = '';
  for (const character of text) {
    if (isAlphanumeric(character) || character === '_') current += character;
    else {
      if (current) out.push(current);
      current = '';
    }
  }
  if (current) out.push(current);
  return out;
}

